import type { CareerPathStage, Tournament } from '../types/game'
import { inferTournamentFormatId } from './tournamentFormats'

function createTournament(entry: Tournament): Tournament {
  return {
    formatId: entry.formatId ?? inferTournamentFormatId(entry),
    totalPrizeFund: entry.prizeMoney,
    winnerPrize: Math.round(entry.prizeMoney * 0.5),
    runnerUpPrize: Math.round(entry.prizeMoney * 0.22),
    semiFinalPrize: Math.round(entry.prizeMoney * 0.08),
    quarterFinalPrize: Math.round(entry.prizeMoney * 0.03),
    firstRoundPrize: 0,
    rankingType: 'None',
    prestige: 1,
    unlockRequirement: 'Pathway access required.',
    progressionImpact: 'Builds momentum inside the pathway.',
    reward: undefined,
    ...entry,
  }
}

